            cells = []
            queue = [(r, c)]
            visited.add((r, c))

            while queue:
                cr, cc = queue.pop(0)
                cells.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if (0 <= nr < len(result) and 0 <= nc < len(result[0])
                        and (nr, nc) not in visited and result[nr][nc] == val):
                        visited.add((nr, nc))
                        queue.append((nr, nc))

            if len(cells) < 8:
