            rows_s = sorted(set(x[0] for x in cells))
            cols_s = sorted(set(x[1] for x in cells))
            top, bottom = rows_s[0], rows_s[-1]
            left, right = cols_s[0], cols_s[-1]

            # Verify frame structure
            is_frame = True
            for rf in [top, bottom]:
                for cf in range(left, right + 1):
                    if (rf, cf) not in cells or result[rf][cf] != val:
                        is_frame = False
                        break
                if not is_frame:
                    break
            if not is_frame:
                continue

            for cf in [left, right]:
                for rf in range(top + 1, bottom):
                    if (rf, cf) not in cells or result[rf][cf] != val:
                        is_frame = False
                        break
                if not is_frame:
                    break
            if not is_frame:
                continue

            # Interior bounds
            it, ib = top + 1, bottom - 1
            il, ir = left + 1, right - 1

            if it > ib or il > ir:
                continue

            ih = ib - it + 1

            # Fill: 7 if inner dimension is odd, 2 if even
